import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        int nextInt() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return Integer.parseInt(st.nextToken());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int hpY = fs.nextInt();
        int atkY = fs.nextInt();
        int defY = fs.nextInt();

        int hpM = fs.nextInt();
        int atkM = fs.nextInt();
        int defM = fs.nextInt();

        int hpCost = fs.nextInt();
        int atkCost = fs.nextInt();
        int defCost = fs.nextInt();

        long answer = Long.MAX_VALUE;

        for (int atk = atkY; atk <= defM + hpM; atk++) {
            int damageToMonster = Math.max(1, atk - defM);
            int turns = (hpM + damageToMonster - 1) / damageToMonster;

            for (int def = defY; def <= atkM; def++) {
                int damageToYang = Math.max(0, atkM - def);
                int requiredHp = turns * damageToYang + 1;

                long cost = (long) (atk - atkY) * atkCost
                        + (long) (def - defY) * defCost
                        + (long) Math.max(0, requiredHp - hpY) * hpCost;

                answer = Math.min(answer, cost);
            }
        }

        System.out.println(answer);
    }
}

