        int defM = sc.nextInt();

        int hpCost = sc.nextInt();
        int atkCost = sc.nextInt();
        int defCost = sc.nextInt();

        long answer = Long.MAX_VALUE;

        for (int atk = atkY; atk <= defM + hpM; atk++) {
            int damageToMonster = atk - defM;
            if (damageToMonster <= 0) continue;

            int turns = (hpM + damageToMonster - 1) / damageToMonster;

            for (int def = defY; def <= atkM; def++) {
                int damageToYang = Math.max(0, atkM - def);
                int requiredHp = turns * damageToYang + 1;
                int hpToBuy = Math.max(0, requiredHp - hpY);

                long totalCost = (long) hpToBuy * hpCost
                        + (long) (atk - atkY) * atkCost
                        + (long) (def - defY) * defCost;

                answer = Math.min(answer, totalCost);
            }
        }

        System.out.println(answer);
    }
}

