        int hpCost = sc.nextInt();
        int atkCost = sc.nextInt();
        int defCost = sc.nextInt();

        long minCost = Long.MAX_VALUE;

        for (int atk = atkY; atk <= defM + hpM; atk++) {
            int damageToMonster = atk - defM;
            if (damageToMonster <= 0) continue;

            long turns = (hpM + damageToMonster - 1L) / damageToMonster;

            for (int def = defY; def <= Math.max(defY, atkM); def++) {
                int damageToYang = Math.max(0, atkM - def);
                long requiredHp = turns * damageToYang + 1;
                long hpIncrease = Math.max(0L, requiredHp - hpY);

                long cost = hpIncrease * hpCost
                        + (long) (atk - atkY) * atkCost
                        + (long) (def - defY) * defCost;

                minCost = Math.min(minCost, cost);
            }
        }

        System.out.println(minCost);
    }
}
